           std::min(a.y, c.y) - 1e-12 <= b.y && b.y <= std::max(a.y, c.y) + 1e-12;  
};  

auto segIntersect = [&](const Point2d& p1, const Point2d& q1, const Point2d& p2, const Point2d& q2) {  
    int o1 = orient(p1, q1, p2);  
    int o2 = orient(p1, q1, q2);  
    int o3 = orient(p2, q2, p1);  
    int o4 = orient(p2, q2, q1);  

    if (o1 != o2 && o3 != o4) return true;  

    if (o1 == 0 && onSegment(p1, p2, q1)) return true;  
    if (o2 == 0 && onSegment(p1, q2, q1)) return true;  
    if (o3 == 0 && onSegment(p2, p1, q2)) return true;  
    if (o4 == 0 && onSegment(p2, q1, q2)) return true;  

    return false;  
};  

// Edge‑edge intersection test  
for (std::size_t i = 0; i < n1; ++i) {  
    const Point2d& a1 = P1[i];  
    const Point2d& b1 = P1[(i + 1) % n1];  
    for (std::size_t j = 0; j < n2; ++j) {  
        const Point2d& a2 = P2[j];  
        const Point2d& b2 = P2[(j + 1) % n2];  
        if (segIntersect(a1, b1, a2, b2)) return true;  
    }  
}  

auto pointInPoly = [&](const Polygon2d& poly, const Point2d& pt) {  
    std::size_t n = poly.size();  
    if (n < 3) return false;  
    bool inside = false;  
    for (std::size_t i = 0, j = n - 1; i < n; j = i++) {  
        const Point2d& pi = poly[i];  
        const Point2d& pj = poly[j];  

        // Check if point is exactly on an edge  
        if (std::abs((pj.y - pi.y) * (pt.x - pi.x) - (pj.x - pi.x) * (pt.y - pi.y)) < 1e-12 &&  
            std::min(pi.x, pj.x) - 1e-12 <= pt.x && pt.x <= std::max(pi.x, pj.x) + 1e-12 &&  
            std::min(pi.y, pj.y) - 1e-12 <= pt.y && pt.y <= std::max(pi.y, pj.y) + 1e-12) {  
            return true;  
        }  

        bool intersect = ((pi.y > pt.y) != (pj.y > pt.y)) &&  
                         (pt.x < (pj.x - pi.x) * (pt.y - pi.y) / (pj.y - pi.y + 1e-12) + pi.x);  
        if (intersect) inside = !inside;  
    }  
    return inside;  
};  

// Vertex‑in‑polygon test  
if (pointInPoly(P1, P2[0])) return true;  
if (pointInPoly(P2, P1[0])) return true;  

return false;

